import React,{useState,useMemo,useEffect} from 'react';
import {ArrowRight,ArrowUpRight,ArrowLeft,ChartNoAxesCombined,Quote,GitBranch,FlaskConical,Code2,ScanLine,LayoutDashboard,Archive,Database,Settings,Menu,X,Check,Plus,Download,Search,ShieldCheck,Info,Trash2,Copy,Clock,FileText,ChevronRight,Save,Link2,Target} from 'lucide-react';
import {useApp,Link,Button,Badge,Logo,Lang,Credit,Card,PageHeader,Field,Input,Textarea,Select,Empty,Next} from './components/ui';
import {stages,eventLabels,defaultOptions,starterHypothesis,starterRationale,decisionMarkdown} from './domain/content.mjs';
import {DEFAULT_FILTERS,EVENTS,compareSegments,sampleSize,twoArmMetrics,metricsFromCounts} from './domain/analytics.mjs';
import {download} from './domain/storage.mjs';
import DataManager from './DataManager';
import CountUp from './components/CountUp';
import CasePicker from './components/CasePicker';
import {getCase,caseOptions,caseFilters,caseExperiment,caseBrief} from './domain/cases.mjs';
const icons=[ChartNoAxesCombined,Quote,GitBranch,FlaskConical,Code2,ScanLine];
function Provenance(){const {dataset,t,stepEvents:EVENTS,stepLabels:eventLabels,config,unit}=useApp();return <Badge type={dataset.provenance==='synthetic_demo'?'teal':'amber'} dot>{dataset.provenance==='synthetic_demo'?t('SYNTHETIC DATA','DỮ LIỆU GIẢ LẬP'):t('IMPORTED DATA','DỮ LIỆU ĐÃ NHẬP')}</Badge>;}
function SectionHead({index}){const {t,c,stepEvents:EVENTS,stepLabels:eventLabels,config,unit}=useApp();const s=stages[index];return <PageHeader eyebrow={`0${index+1} / ${c([s[1],s[2]]).toUpperCase()}`} title={c([s[5],s[6]])} subtitle={c([s[3],s[4]])}><Provenance/></PageHeader>;}
function Kpis(){const {funnel,n,percent,t,c,state,stepEvents:EVENTS,stepLabels:eventLabels,config,unit}=useApp();return <div className="kpi-grid">{funnel.steps.map((s,i)=><div className={'kpi '+(i===config.primaryIndex?'accent':'')} key={i}><span>{c(eventLabels[i])}</span><strong><CountUp value={i===0?s.users:s.cumulative_conversion} kind={i===0?'count':'percent'} language={state.language}/></strong><small>{i?`${n(s.users)} / ${n(funnel.counts[0])} ${unit}`:t('Unique cohort entries','Đơn vị duy nhất trong cohort')}</small></div>)}</div>;}
function LabEntry(){const {t,setState,navigate,switchCase,stepEvents:EVENTS,stepLabels:eventLabels,config,unit}=useApp();return <div className="lab-entry"><span className="eyebrow">{t('YOUR NEXT PRODUCT DECISION STARTS HERE','QUYẾT ĐỊNH SẢN PHẨM TIẾP THEO BẮT ĐẦU TỪ ĐÂY')}</span><h1>{t('Welcome to the Lab.','Chào mừng đến Lab.')}</h1><p>{t('Bring a question. Find the signals. Leave with a better bet.','Mang theo câu hỏi. Tìm tín hiệu. Hoàn thành quyết định có cơ sở hơn.')}</p><div className="entry-grid"><Card className="demo-entry"><div className="entry-icon"><GitBranch size={34}/></div><Badge type="teal">{t('RECOMMENDED','GỢI Ý')}</Badge><h2>{t('Explore the Demo','Khám phá demo')}</h2><p>{t('Investigate an onboarding funnel for OrbitDesk, a fictional B2B SaaS product. Real interactions. Synthetic data.','Phân tích funnel onboarding của OrbitDesk, một SaaS B2B giả lập. Tương tác thực tế. Dữ liệu giả lập.')}</p><div className="entry-stats"><span><strong>12,000</strong>{t('users','người dùng')}</span><span><strong>06</strong>{t('connected stages','bước kết nối')}</span></div><Button arrow onClick={()=>{switchCase('orbitdesk');navigate('/lab/diagnose');}}>{t('Start Guided Demo','Bắt đầu demo có hướng dẫn')}</Button></Card><Card><div className="entry-icon"><Database size={34}/></div><Badge>{t('LOCAL-FIRST','XỬ LÝ CỤC BỘ')}</Badge><h2>{t('Analyze Your Data','Phân tích dữ liệu của bạn')}</h2><p>{t('Download the case template and upload your event CSV. Analysis uses your uploaded rows.','Tải mẫu case và nhập CSV sự kiện. Phân tích dùng các dòng bạn tải lên.')}</p><div className="schema-chips"><code>entity_id</code><code>event_name</code><code>timestamp</code></div><Button to="/lab/data" secondary arrow>{t('Import CSV','Nhập CSV')}</Button></Card></div><CasePicker cards/><div className="entry-privacy"><ShieldCheck size={21}/><p>{t('No account needed. Work is stored on this device. Export important decisions for backup. Local browser storage is not a secure enterprise vault.','Không cần tài khoản. Công việc lưu trên thiết bị. Xuất quyết định quan trọng để sao lưu. Bộ nhớ trình duyệt không phải kho lưu trữ doanh nghiệp bảo mật.')}</p></div></div>;}
function Overview(){const {t,state,decision,n,c,stepEvents:EVENTS,stepLabels:eventLabels,config,unit}=useApp();return <><PageHeader eyebrow={t('MISSION CONTROL','TỔNG QUAN')} title={t('Your next product decision.','Quyết định sản phẩm tiếp theo.')} subtitle={t('A clear question. A connected investigation.','Một câu hỏi rõ. Một hành trình kết nối.')}><Button to="/lab/diagnose" arrow>{t('Continue Investigation','Tiếp tục phân tích')}</Button></PageHeader><Card className="mission-question"><Badge type="teal">{t('CURRENT QUESTION','CÂU HỎI HIỆN TẠI')}</Badge><h2>{c(config.question)}</h2><div className="row"><Provenance/><span className="muted">{c(config.method)}</span></div></Card><Kpis/><div className="two-col"><Card title={t('The decision loop','Vòng lặp quyết định')}><div className="overview-loop">{stages.map((s,i)=><Link to={'/lab/'+s[0]} key={s[0]}><span className="loop-number">0{i+1}</span><div><h3>{c([s[1],s[2]])}</h3><p>{c([s[3],s[4]])}</p></div><ArrowUpRight size={18}/></Link>)}</div></Card><div className="stack"><Card title={t('Your current bet','Lựa chọn hiện tại')}>{decision?<><Badge type="teal">{decision.id}</Badge><h3>{decision.title}</h3><p>{decision.hypothesis}</p><Button to="/lab/decisions" secondary>{t('Open Decision Archive','Mở kho quyết định')}</Button></>:<Empty title={t('No saved bet yet','Chưa lưu quyết định')} body={t('Start with the funnel, link evidence and compare at least two alternatives.','Bắt đầu từ funnel, liên kết bằng chứng và so sánh ít nhất hai phương án.')}><Button to="/lab/diagnose" secondary>{t('Start with behavior','Bắt đầu từ hành vi')}</Button></Empty>}</Card><Card title={t('Your activity on this device','Hoạt động trên thiết bị này')}>{state.activity.length?<div className="activity-list">{state.activity.slice(-6).reverse().map((a,i)=><div key={i}><i/><div><span>{c(a.label)}</span><time>{new Date(a.at).toLocaleString(state.language==='vi'?'vi-VN':'en-GB')}</time></div></div>)}</div>:<p className="muted">{t('Actions you take will appear here. No simulated team activity.','Hành động của bạn sẽ hiện ở đây. Chưa có hoạt động nào.')}</p>}</Card></div></div></>;}
function Diagnose(){const {t,c,state,setState,funnel,dataset,n,percent,toast,navigate,log,stepEvents:EVENTS,stepLabels:eventLabels,config,unit}=useApp();const [mode,setMode]=useState('cohort');const [property,setProperty]=useState('device');const f=state.filters;
 const update=(key,value)=>setState(s=>({...s,filters:{...s.filters,[key]:value}}));
 const segment=useMemo(()=>compareSegments(dataset.events,f,dataset.observation_end_at,property,EVENTS,config),[dataset,f,property]);const selected=state.selectedStep,s=funnel.steps[selected];
 const options=key=>[['all',t('All','Tất cả')],...[...new Set(dataset.events.filter(e=>e.event_name===EVENTS[0]).map(e=>e[key]||'unknown'))].sort().map(v=>[v,translateCategory(v,t)])];
 const save=()=>{if(!funnel.counts[0]){toast(t('Choose a cohort with data first.','Hãy chọn cohort có dữ liệu trước.'));return;}setState(st=>({...st,investigation:{id:'ISSUE-'+Date.now(),step:selected,event:EVENTS[selected],filters:{...f},baseline:{counts:[...funnel.counts]},dataset_fingerprint:dataset.fingerprint,provenance:dataset.provenance,at:new Date().toISOString()},activity:[...st.activity,{label:['Investigation saved','Đã lưu phân tích'],at:new Date().toISOString()}]}));toast(t('Investigation saved locally.','Đã lưu phân tích trên thiết bị.'));navigate('/lab/evidence');};
 return <><SectionHead index={0}/><Card className="filter-panel"><div className="filter-grid"><Input label={t('Cohort entry from','Cohort bắt đầu từ')} type="date" value={f.from} onChange={e=>update('from',e.target.value)}/><Input label={t('Cohort entry to','Cohort bắt đầu đến')} type="date" value={f.to} onChange={e=>update('to',e.target.value)}/><Select label={t('Device','Thiết bị')} value={f.device} options={options('device')} onChange={e=>update('device',e.target.value)}/><Select label={t('Channel','Kênh')} value={f.acquisition_channel} options={options('acquisition_channel')} onChange={e=>update('acquisition_channel',e.target.value)}/><Select label={t('Plan','Gói')} value={f.plan_type} options={options('plan_type')} onChange={e=>update('plan_type',e.target.value)}/><Select label={t('Conversion window','Cửa sổ chuyển đổi')} value={f.days} options={[...new Set([1,7,14,21,30,45,config.days])].sort((a,b)=>a-b).map(d=>[d,`${d} ${t('days','ngày')}`])} onChange={e=>update('days',Number(e.target.value))}/></div><div className="row between filter-bottom"><div className="row"><Select label={t('Country','Quốc gia')} value={f.country} options={options('country')} onChange={e=>update('country',e.target.value)}/><label className="check-label"><input type="checkbox" checked={f.excludeIncomplete} onChange={e=>update('excludeIncomplete',e.target.checked)}/>{t('Exclude incomplete follow-up','Loại thời gian theo dõi chưa đủ')}</label></div><Button quiet onClick={()=>setState(s=>({...s,filters:caseFilters(config)}))}>{t('Reset filters','Đặt lại bộ lọc')}</Button></div></Card>{funnel.incomplete>0&&<div className="notice amber"><Clock size={18}/><p>{n(funnel.incomplete)} {t('cohort entries do not have full follow-up through the observation end. This can understate conversion.','người dùng chưa được theo dõi đủ đến cuối kỳ. Điều này có thể làm giảm tỷ lệ chuyển đổi.')} {t('Observation ends','Kết thúc quan sát')}: {dataset.observation_end_at.slice(0,10)}</p></div>}<Kpis/>{!funnel.counts[0]?<Card><Empty title={t('No cohort entries match these filters','Không có người dùng phù hợp bộ lọc')} body={t('Try a broader entry date range or reset the filters.','Mở rộng khoảng thời gian hoặc đặt lại bộ lọc.')}/></Card>:<div className="diagnose-grid"><Card title={t('Ordered milestone funnel','Funnel mốc tiến độ có thứ tự')} aside={<Badge>{unit.toUpperCase()}</Badge>}><div className="metric-tabs" role="group" aria-label={t('Funnel display mode','Chế độ hiển thị funnel')}>{[['count',t('Counts','Số lượng')],['cohort',t('% of cohort','% cohort')],['previous',t('% previous','% bước trước')],['dropoff',t('Drop-off','Rời đi')]].map(([k,label])=><button key={k} aria-pressed={mode===k} className={mode===k?'active':''} onClick={()=>setMode(k)}>{label}</button>)}</div><div className="funnel-bars">{funnel.steps.map((step,i)=><button className={'funnel-row '+(i===selected?'selected':'')} key={i} aria-pressed={i===selected} onClick={()=>setState(s=>({...s,selectedStep:i}))}><div className="funnel-label"><span><small>0{i+1}</small>{c(eventLabels[i])}</span><strong><CountUp value={mode==='count'?step.users:mode==='cohort'?step.cumulative_conversion:mode==='previous'?step.previous_step_conversion:step.dropoff_rate} kind={mode==='count'?'count':'percent'} language={state.language}/></strong></div><div className="funnel-track"><span style={{width:`${step.cumulative_conversion*100}%`}}/><i/></div><div className="funnel-meta"><span>{n(step.users)} {unit}</span><span>{i?`${n(step.dropoff_users)} ${t('lost from previous','rời đi so với bước trước')}`:t('Earliest eligible entry','Lần bắt đầu hợp lệ đầu tiên')}</span></div></button>)}</div><details className="calculation"><summary>{t('See calculation & metric definitions','Xem phép tính & định nghĩa chỉ số')}</summary><p>{t('Unique entities, not events. Each entity enters at its earliest eligible first milestone within the date range. Later steps must occur strictly in order within the selected elapsed-time window. Segment properties are taken from the entry event.','Đếm đơn vị duy nhất, không đếm sự kiện. Mỗi đơn vị bắt đầu từ mốc đầu hợp lệ trong khoảng ngày. Các bước sau phải xảy ra đúng thứ tự trong cửa sổ thời gian. Thuộc tính phân khúc lấy tại sự kiện đầu vào.')}</p><p>{t('Cohort rate = step entities ÷ entry entities. Step rate = step entities ÷ previous step entities. Drop-off = 1 − step rate. A missing required step prevents credit for later steps.','Tỷ lệ cohort = đơn vị đạt bước ÷ đơn vị đầu vào. Tỷ lệ bước = đơn vị đạt bước ÷ đơn vị đạt bước trước. Rời đi = 1 − tỷ lệ bước. Thiếu bước bắt buộc sẽ không ghi nhận bước sau.')}</p></details></Card><Card className="inspector"><span className="eyebrow">{t('BOTTLENECK INSPECTOR','PHÂN TÍCH ĐIỂM NGHẼN')}</span><Badge type="teal">{t('OBSERVED','QUAN SÁT ĐƯỢC')}</Badge><h2>{c(eventLabels[selected])}</h2><div className="inspector-stat"><strong><CountUp value={s.dropoff_users??s.users} language={state.language}/></strong><span>{selected?t('units lost at this step','đơn vị chưa đạt bước này'):t('unique cohort entries','đơn vị duy nhất trong cohort')}</span></div><div className="inspector-rate"><strong><CountUp value={s.dropoff_rate} kind="percent" language={state.language}/></strong><span>{t('drop-off from previous step','rời đi so với bước trước')}</span></div><hr/><p>{t('A behavior pattern is an observation. It does not tell us why people left.','Hành vi là điều quan sát được. Chưa giải thích vì sao người dùng rời đi.')}</p><Button arrow onClick={save}>{t('Save & Investigate Evidence','Lưu & tìm bằng chứng')}</Button><Link to="/lab/data" className="text-link">{t('Inspect the data source','Kiểm tra nguồn dữ liệu')}<ArrowUpRight size={16}/></Link></Card></div>}<Card className="signal-note"><div><Badge type="teal">{t('OBSERVED','QUAN SÁT')}</Badge><p>{selected&&funnel.counts[0]?`${n(s.users)} / ${n(funnel.counts[selected-1])} ${unit+' '+t('reached','đạt')} ${c(eventLabels[selected]).toLowerCase()} · ${percent(s.previous_step_conversion)}`:t('Select a funnel step to begin an investigation.','Chọn bước funnel để bắt đầu phân tích.')}</p></div><div><Badge type="amber">{t('QUESTION','CÂU HỎI')}</Badge><p>{t('Is this requirement creating friction, or is another issue present?','Yêu cầu này tạo cản trở hay còn nguyên nhân khác?')}</p></div></Card><Card title={t('Segment comparison','So sánh phân khúc')} aside={<Select label={t('Compare by','So sánh theo')} value={property} onChange={e=>setProperty(e.target.value)} options={[['device',t('Device','Thiết bị')],['acquisition_channel',t('Channel','Kênh')],['plan_type',t('Plan','Gói')],['country',t('Country','Quốc gia')]]}/>}><div className="table-wrap"><table><thead><tr><th>{t('Segment','Phân khúc')}</th>{eventLabels.map(v=><th key={v[0]}>{c(v)}</th>)}<th>{c(eventLabels[config.primaryIndex])}</th></tr></thead><tbody>{segment.map(v=><tr key={v.name}><th>{translateCategory(v.name,t)}</th>{v.counts.map((x,i)=><td key={i}>{n(x)}</td>)}<td><strong>{percent(v.activation)}</strong>{v.counts[0]<100&&<Badge type="amber">{t('Small sample','Mẫu nhỏ')}</Badge>}</td></tr>)}</tbody></table></div><p className="caption">{t('Descriptive comparison only. Differences do not establish causation or statistical significance.','Chỉ so sánh mô tả. Chênh lệch chưa chứng minh nguyên nhân hay ý nghĩa thống kê.')}</p></Card><div className="row end"><Button secondary onClick={()=>download('betterbet-funnel.csv','event,users,cohort_rate,previous_step_rate\n'+funnel.steps.map(x=>[x.event_name,x.users,x.cumulative_conversion??'',x.previous_step_conversion??''].join(',')).join('\n'),'text/csv') }><Download size={17}/>{t('Export Funnel CSV','Xuất funnel CSV')}</Button></div></>;
}
export function translateCategory(v,t){return ({desktop:t('Desktop','Máy tính'),mobile:t('Mobile','Điện thoại'),organic:t('Organic','Tự nhiên'),paid:t('Paid','Trả phí'),referral:t('Referral','Giới thiệu'),free:t('Free','Miễn phí'),trial:t('Trial','Dùng thử'),unknown:t('Unknown','Chưa rõ'),high:t('High','Cao'),medium:t('Medium','Trung bình'),low:t('Low','Thấp'),support:t('Supports','Ủng hộ'),counter:t('Challenges','Trái chiều'),alternative:t('Alternative explanation','Giải thích khác'),support_ticket:t('Support ticket','Phiếu hỗ trợ'),interview_note:t('Interview note','Ghi chú phỏng vấn'),survey:t('Survey','Khảo sát'),usability_test:t('Usability test','Kiểm thử dễ dùng'),other:t('Manual note','Ghi chú tự nhập')})[v]||v;}
function Evidence(){const {t,c,state,setState,toast,confirm,dataset,stepEvents:EVENTS,stepLabels:eventLabels,config,unit}=useApp();const [query,setQuery]=useState(''),[stance,setStance]=useState('all'),[source,setSource]=useState('all'),[editing,setEditing]=useState(null),[synthesis,setSynthesis]=useState(false);
 const items=state.evidence.filter(e=>!e.workspace_id||e.workspace_id===dataset.id).filter(e=>[e.body,e.body_vi,e.notes,e.tags.join(' ')].join(' ').toLowerCase().includes(query.toLowerCase())&&(stance==='all'||e.stance===stance)&&(source==='all'||e.source_type===source));
 const linked=state.evidence.filter(e=>e.linked&&e.issue===EVENTS[state.selectedStep]&&(!e.workspace_id||e.workspace_id===dataset.id));const update=(id,patch)=>setState(s=>({...s,evidence:s.evidence.map(e=>e.id===id?{...e,...patch}:e)}));
 const saveNote=()=>{if(!editing.body.trim()||!editing.source_reference.trim()){toast(t('Add the quote and its source reference.','Điền nội dung và nguồn tham chiếu.'));return;}setState(s=>({...s,evidence:s.evidence.some(e=>e.id===editing.id)?s.evidence.map(e=>e.id===editing.id?editing:e):[...s.evidence,editing],activity:[...s.activity,{label:['Evidence note saved','Đã lưu ghi chú bằng chứng'],at:new Date().toISOString()}]}));setEditing(null);toast(t('Evidence saved locally.','Đã lưu bằng chứng trên thiết bị.'));};
 return <><SectionHead index={1}/><div className="context-line"><Link to="/lab/diagnose">{t('Observed step','Bước quan sát')}: {c(eventLabels[state.selectedStep])}</Link><ChevronRight size={15}/><span>{linked.length} {t('linked sources','nguồn liên kết')}</span><ChevronRight size={15}/><Badge type="amber">{t('HYPOTHESIS','GIẢ THUYẾT')}</Badge></div><div className="row between evidence-toolbar"><div className="search-field"><Search size={18}/><input aria-label={t('Search evidence','Tìm bằng chứng')} placeholder={t('Search quotes, tags, notes…','Tìm nội dung, thẻ, ghi chú…')} value={query} onChange={e=>setQuery(e.target.value)}/></div><Select label={t('Stance','Quan điểm')} value={stance} options={['all','support','counter','alternative','unknown'].map(v=>[v,v==='all'?t('All perspectives','Mọi quan điểm'):translateCategory(v,t)])} onChange={e=>setStance(e.target.value)}/><Select label={t('Source','Nguồn')} value={source} options={['all','support_ticket','interview_note','survey','usability_test','other'].map(v=>[v,v==='all'?t('All sources','Mọi nguồn'):translateCategory(v,t)])} onChange={e=>setSource(e.target.value)}/><Button secondary onClick={()=>setEditing({id:'E-'+Date.now(),workspace_id:dataset.id,body:'',source_type:'other',source_reference:'',source_date:new Date().toISOString().slice(0,10),provenance:'user_authored',stance:'unknown',tags:[],notes:'',linked:false,issue:EVENTS[state.selectedStep]})}><Plus size={17}/>{t('Add Note','Thêm ghi chú')}</Button></div>{editing&&<Card className="note-editor" title={t('Edit evidence record','Sửa hồ sơ bằng chứng')}><div className="two-col"><Textarea label={t('Quote / observation','Trích dẫn / quan sát')} value={editing.body} onChange={e=>setEditing({...editing,body:e.target.value,body_vi:undefined})}/><Textarea label={t('Your annotation','Ghi chú của bạn')} value={editing.notes} onChange={e=>setEditing({...editing,notes:e.target.value})}/></div><div className="filter-grid"><Input label={t('Source reference (required)','Nguồn tham chiếu (bắt buộc)')} value={editing.source_reference} onChange={e=>setEditing({...editing,source_reference:e.target.value})}/><Input label={t('Source date','Ngày nguồn')} type="date" value={editing.source_date} onChange={e=>setEditing({...editing,source_date:e.target.value})}/><Select label={t('Source type','Loại nguồn')} value={editing.source_type} options={['support_ticket','interview_note','survey','usability_test','other'].map(v=>[v,translateCategory(v,t)])} onChange={e=>setEditing({...editing,source_type:e.target.value})}/><Select label={t('Evidence stance','Quan điểm bằng chứng')} value={editing.stance} options={['support','counter','alternative','unknown'].map(v=>[v,translateCategory(v,t)])} onChange={e=>setEditing({...editing,stance:e.target.value})}/><Input label={t('Tags (comma-separated)','Thẻ (cách nhau bằng dấu phẩy)')} value={editing.tags.join(', ')} onChange={e=>setEditing({...editing,tags:e.target.value.split(',').map(x=>x.trim())})}/></div><p className="caption">{t('Only record genuine sources you have permission to use. User notes are marked manually authored.','Chỉ ghi nguồn thực tế được phép sử dụng. Ghi chú của bạn được đánh dấu tự nhập.')}</p><div className="row end"><Button quiet onClick={()=>setEditing(null)}>{t('Cancel','Hủy')}</Button><Button onClick={saveNote}>{t('Save Evidence','Lưu bằng chứng')}</Button></div></Card>}<div className="evidence-layout"><div className="evidence-grid">{items.length?items.map(e=><article className={'evidence-card '+e.stance} key={e.id}><div className="row between"><span className="source-meta">{e.id} / {translateCategory(e.source_type,t)}</span><Badge type={e.stance==='counter'?'rose':e.stance==='alternative'?'amber':'teal'}>{translateCategory(e.stance,t)}</Badge></div><Quote size={22} className="quote-icon"/><blockquote>{state.language==='vi'&&e.body_vi?e.body_vi:e.body}</blockquote><div className="evidence-tags">{e.tags.filter(Boolean).map(tag=><span key={tag}>{translateTag(tag,t)}</span>)}</div><details className="evidence-details"><summary>{t('Source & notes','Nguồn & ghi chú')}</summary><p>{e.source_reference}</p><p>{e.notes||t('No annotations yet.','Chưa có ghi chú.')}</p><p>{e.provenance==='synthetic_demo'?t('Synthetic research note for demonstration','Ghi chú nghiên cứu giả lập để minh họa'):t('Manually recorded source; not verified by Betterbet','Nguồn ghi thủ công; Betterbet chưa xác minh')}</p><div className="row"><Button quiet onClick={()=>setEditing({...e})}>{t('Edit','Sửa')}</Button><button className="icon-btn danger" aria-label={t('Delete note','Xóa ghi chú')} onClick={async()=>{if(await confirm(t('Delete this note?','Xóa ghi chú này?'),t('This removes it from the active evidence list. Saved decisions retain their snapshots.','Ghi chú bị xóa khỏi danh sách hiện tại. Quyết định đã lưu vẫn giữ bản chụp.')))setState(s=>({...s,evidence:s.evidence.filter(x=>x.id!==e.id)}));}}><Trash2 size={16}/></button></div></details><footer><span>{e.source_date} · {e.provenance==='synthetic_demo'?t('Synthetic','Giả lập'):t('Manual','Tự nhập')}</span><button className={'link-evidence '+(e.linked?'linked':'')} onClick={()=>{update(e.id,{linked:!e.linked,issue:EVENTS[state.selectedStep]});toast(e.linked?t('Evidence unlinked.','Đã bỏ liên kết.'):t('Evidence linked to current issue.','Đã liên kết với vấn đề hiện tại.'));}}>{e.linked?<Check size={15}/>:<Plus size={15}/>} {e.linked?t('Linked','Đã liên kết'):t('Link','Liên kết')}</button></footer></article>):<Card><Empty title={t('No sources match','Không có nguồn phù hợp')} body={t('Clear your filters or add a genuine source note.','Xóa bộ lọc hoặc thêm ghi chú nguồn thực tế.')}/></Card>}</div><aside className="evidence-rail"><Card title={t('Evidence coverage','Mức bao phủ bằng chứng')}><strong className="coverage-number">{linked.length}</strong><p>{t('sources linked to this issue','nguồn liên kết với vấn đề này')}</p><div className="coverage-breakdown">{['support','counter','alternative','unknown'].map(s=><div key={s}><span>{translateCategory(s,t)}</span><strong>{linked.filter(e=>e.stance===s).length}</strong></div>)}</div><p className="caption">{t('Quote count is not scientific confidence.','Số trích dẫn không thể hiện độ tin cậy khoa học.')}</p></Card><Card title={t('What would change your mind?','Điều gì khiến bạn đổi ý?')}><p>{t('Look for a successful onboarding story or a different cause. Disconfirming evidence is a feature of good reasoning.','Tìm câu chuyện onboarding thành công hoặc nguyên nhân khác. Bằng chứng trái chiều là một phần tư duy tốt.')}</p><Button secondary onClick={()=>{setStance('counter');setSource('all');setQuery('');}}>{t('Find Counterevidence','Tìm bằng chứng trái chiều')}</Button></Card><Card title={t('Draft a hypothesis','Phác thảo giả thuyết')}><Textarea label={t('Unconfirmed mechanism','Cơ chế chưa xác minh')} value={c(state.hypothesis)} onChange={e=>setState(s=>({...s,hypothesis:e.target.value}))}/><Button secondary disabled={!linked.length} onClick={()=>setSynthesis(!synthesis)}>{t('Synthesize Linked Sources','Tổng hợp nguồn liên kết')}</Button>{synthesis&&<div className="synthesis"><Badge type="amber">{t('RULES-ASSISTED DRAFT','BẢN NHÁP THEO QUY TẮC')}</Badge><p>{linked.map(e=>e.id).join(', ')}</p><p>{linked.filter(e=>e.stance==='support').length} {t('supporting sources,','nguồn ủng hộ,')} {linked.filter(e=>e.stance==='counter').length} {t('challenging sources. Representativeness and causation remain unvalidated.','nguồn trái chiều. Tính đại diện và nguyên nhân chưa xác minh.')}</p></div>}</Card></aside></div><Next to="/lab/decide" title={t('Compare Options','So sánh phương án')} body={t('Bring the observation and linked sources into the Decision Canvas.','Mang quan sát và nguồn liên kết sang phần ra quyết định.')}/></>;
}
function translateTag(tag,t){return ({'premature commitment':t('Premature commitment','Cam kết quá sớm'),'solo evaluation':t('Solo evaluation','Tự tìm hiểu'),'mobile reliability':t('Mobile reliability','Ổn định điện thoại'),'collaboration':t('Collaboration','Cộng tác'),'empty states':t('Empty states','Trạng thái trống'),'invite anxiety':t('Invite anxiety','Lo ngại lời mời'),'attention':t('Attention','Sự chú ý'),'unclear value':t('Unclear value','Giá trị chưa rõ'),'business constraints':t('Business constraints','Giới hạn kinh doanh'),'needs validation':t('Needs validation','Cần xác minh')})[tag]||tag;}
function DecisionDNA({decision:record}){const {t,c,state,decision:current,activateDecision,stepEvents:EVENTS,stepLabels:eventLabels,config,unit}=useApp();const recordToShow=record||current;const options=recordToShow?.options||state.options;const chosen=recordToShow?.chosen||state.chosen;const sources=recordToShow?.evidence||state.evidence.filter(e=>e.linked);const open=()=>{if(recordToShow)activateDecision(recordToShow);};return <div className="decision-dna"><div className="row between"><span className="eyebrow">DECISION DNA</span><span className="caption">{t('A traceable reasoning path','Dấu vết tư duy có thể truy vết')}</span></div><div className="dna-path"><Link to="/lab/diagnose" className="dna-node" onClick={open}><i/>{t('Observation','Quan sát')}</Link><ArrowRight size={14}/><Link to="/lab/evidence" className="dna-node" onClick={open} title={sources.map(e=>e.id).join(', ')}><i/>{sources.length} {t('sources','nguồn')}</Link><ArrowRight size={14}/><Link to="/lab/decide" className="dna-node" onClick={open}><i/>{t('Hypothesis','Giả thuyết')}</Link></div><div className="dna-alternatives"><span className="caption">{t('Alternatives & dissent','Phương án & góc nhìn trái chiều')}</span><div>{options.map(o=><Link key={o.id} to="/lab/decide" onClick={open} className={'dna-choice '+(o.id===chosen?'chosen':'')}><span>{o.id===chosen?<Check size={13}/>:<GitBranch size={13}/>}</span>{c(o.title)||t('Untitled alternative','Phương án chưa đặt tên')}</Link>)}</div><Link to="/lab/evidence" onClick={open} className="dna-counter">{sources.filter(e=>e.stance==='counter').length} {t('challenging sources remain visible','nguồn trái chiều luôn hiện diện')} ↗</Link></div><div className="dna-path dna-outcome"><Link to="/lab/experiment" onClick={open} className="dna-node"><i/>{t('Metric & experiment','Chỉ số & thử nghiệm')}</Link><ArrowRight size={14}/><Link to="/lab/review" onClick={open} className="dna-node pending"><i/>{t('Review the outcome','Xem kết quả')}</Link><Badge type="amber">{recordToShow&&state.reviews[recordToShow.id]?.saved_at?t('Learning recorded','Đã ghi bài học'):t('OUTCOME PENDING','CHỜ KẾT QUẢ')}</Badge></div></div>;}
function Decide(){const {t,c,state,setState,funnel,dataset,toast,confirm,n,percent,navigate,stepEvents:EVENTS,stepLabels:eventLabels,config,unit}=useApp();const [view,setView]=useState('cards');const [edit,setEdit]=useState(null);const [errors,setErrors]=useState([]);
 const linked=state.evidence.filter(e=>e.linked&&e.issue===EVENTS[state.selectedStep]&&(!e.workspace_id||e.workspace_id===dataset.id));const chosen=state.options.find(o=>o.id===state.chosen);
 const updateOption=(id,patch)=>setState(s=>({...s,options:s.options.map(o=>o.id===id?{...o,...patch}:o)}));
 const save=()=>{const missing=[];if(state.investigation&&(state.investigation.step!==state.selectedStep||JSON.stringify(state.investigation.filters)!==JSON.stringify(state.filters)))missing.push(t('Your diagnosis filters or selected step changed. Save the investigation again to refresh its snapshot.','Bộ lọc hoặc bước đã thay đổi. Lưu lại phân tích để cập nhật bản chụp.'));if(state.options.some(o=>!c(o.title).trim()||!c(o.mechanism).trim()))missing.push(t('Give every alternative a title and a real mechanism.','Đặt tên và mô tả cơ chế thực sự cho mỗi phương án.'));if(state.investigation&&state.investigation.dataset_fingerprint!==dataset.fingerprint)missing.push(t('The dataset changed. Save a fresh investigation first.','Dữ liệu đã thay đổi. Lưu phân tích mới trước.'));if(!state.investigation)missing.push(t('Save an investigation in Diagnose.','Lưu phân tích trong Chẩn đoán.'));if(!linked.length)missing.push(t('Link at least one evidence item.','Liên kết ít nhất một bằng chứng.'));if(state.options.length<2)missing.push(t('Create at least two genuine alternatives.','Tạo ít nhất hai phương án thực sự.'));if(!chosen)missing.push(t('Choose an option.','Chọn một phương án.'));if(!c(state.rationale).trim())missing.push(t('Write your decision rationale.','Viết lý do quyết định.'));if(!c(state.hypothesis).trim())missing.push(t('Write a hypothesis.','Viết giả thuyết.'));setErrors(missing);if(missing.length)return;
  const parent=state.decisions.find(d=>d.id===state.activeDecision);const locked=!!(parent&&(state.experiments[parent.id]?.pre_result_snapshot||state.reviews[parent.id]?.saved_at));const existing=locked?null:parent;const id=existing?.id||`BET-${String(Math.max(0,...state.decisions.map(d=>Number(d.id.replace('BET-',''))||0))+1).padStart(4,'0')}`;const at=new Date().toISOString();const baseline=state.investigation.baseline;
  const snapshot={id,parent_id:locked?parent.id:parent?.parent_id,step:state.investigation.step,dataset_id:dataset.id,case_id:config.id,case_config:config,count_unit:config.unit,title:c(chosen.title),workspace:dataset.name,provenance:state.investigation.provenance,dataset_fingerprint:state.investigation.dataset_fingerprint,issue:c(eventLabels[state.investigation.step]),observation:`${baseline.counts[state.investigation.step]} / ${baseline.counts[Math.max(0,state.investigation.step-1)]} ${unit} reached ${EVENTS[state.investigation.step]}. Ordered unique-entity funnel; not causal evidence.`,baseline,filters:{...state.investigation.filters},hypothesis:c(state.hypothesis),evidence:linked.map(e=>({...e,body:state.language==='vi'&&e.body_vi?e.body_vi:e.body})),options:state.options.map(o=>({...o,title:c(o.title),mechanism:c(o.mechanism),risk:c(o.risk),validation:c(o.validation),confidence:c(o.confidence)})),chosen:state.chosen,rationale:c(state.rationale),revisit:c(state.revisit),metric:{numerator:EVENTS[config.primaryIndex],denominator:EVENTS[0],days:state.investigation.filters.days,unit:config.unit},created_at:existing?.created_at||at,updated_at:at,history:existing?[...(existing.history||[]),{...existing,history:undefined}]:[]};
  setState(s=>({...s,decisions:existing?s.decisions.map(d=>d.id===id?snapshot:d):[...s.decisions,snapshot],activeDecision:id,activity:[...s.activity,{label:['Decision saved: '+id,'Đã lưu quyết định: '+id],at}]}));toast(t('Decision saved locally. Export a copy for backup.','Đã lưu quyết định trên thiết bị. Hãy xuất bản sao để sao lưu.'));navigate('/lab/experiment');};
 return <><SectionHead index={2}/><Card className="decision-context">{state.activeDecision&&<Badge type="teal">{state.activeDecision}</Badge>}<Badge type="teal">{t('OBSERVATION','QUAN SÁT')}</Badge><h2>{c(eventLabels[state.selectedStep])} · {percent(funnel.steps[state.selectedStep].dropoff_rate)} {t('step drop-off','rời đi ở bước')}</h2><p>{linked.length} {t('linked sources. The numbers describe behavior; the mechanism remains a hypothesis.','nguồn liên kết. Con số mô tả hành vi; cơ chế vẫn là giả thuyết.')}</p><Link to="/lab/evidence" className="text-link">{t('Review evidence & counterevidence','Xem bằng chứng & trái chiều')}<ArrowUpRight size={16}/></Link></Card><div className="row between canvas-toolbar"><div className="metric-tabs"><button className={view==='cards'?'active':''} onClick={()=>setView('cards')}>{t('Option Cards','Thẻ phương án')}</button><button className={view==='matrix'?'active':''} onClick={()=>setView('matrix')}>{t('Trade-off Lens','So sánh đánh đổi')}</button></div><Button secondary onClick={()=>{const id='O-'+Date.now();setState(s=>({...s,options:[...s.options,{id,title:'',mechanism:'',impact:'unknown',effort:'unknown',risk:'',validation:'',confidence:''}]}));setEdit(id);}}><Plus size={17}/>{t('Add Alternative','Thêm phương án')}</Button></div><p className="caption">{t('Impact and effort are user-judged assumptions. No score is an observed result.','Tác động và công sức là giả định đánh giá của người dùng. Chưa phải kết quả quan sát.')}</p>{view==='cards'?<div className="option-grid">{state.options.map(o=><article className={'option-card '+(state.chosen===o.id?'chosen':'')} key={o.id}><div className="row between"><span className="option-letter">{o.id.length<3?o.id:t('NEW','MỚI')}</span><button className="choose-option" aria-pressed={state.chosen===o.id} onClick={()=>setState(s=>({...s,chosen:o.id}))}>{state.chosen===o.id?<><Check size={15}/>{t('Selected bet','Đã chọn')}</>:t('Choose this bet','Chọn phương án')}</button></div><h2>{c(o.title)||t('Untitled alternative','Phương án chưa đặt tên')}</h2><p>{c(o.mechanism)||t('Add a real alternative and its mechanism.','Thêm phương án thực sự và cơ chế.')}</p><div className="option-facts"><div><span>{t('Impact assumption','Giả định tác động')}</span><strong>{translateCategory(o.impact,t)}</strong></div><div><span>{t('Effort estimate','Ước lượng công sức')}</span><strong>{translateCategory(o.effort,t)}</strong></div></div><div className="option-risk"><span className="eyebrow">{t('MAIN RISK','RỦI RO CHÍNH')}</span><p>{c(o.risk)||'—'}</p></div><div className="option-footer"><span>{c(o.confidence)}</span><button onClick={()=>setEdit(edit===o.id?null:o.id)}>{t('Edit assumptions','Sửa giả định')} ↗</button></div></article>)}</div>:<Card title={t('Trade-off Lens','So sánh sự đánh đổi')}><div className="trade-lens" role="img" aria-label={t('Estimated effort versus assumed impact. The table below provides exact values.','Công sức ước lượng so với tác động giả định. Bảng dưới có cùng dữ liệu.')}><span className="y-label">{t('ASSUMED IMPACT','TÁC ĐỘNG GIẢ ĐỊNH')} ↑</span><span className="x-label">{t('ESTIMATED DELIVERY EFFORT','CÔNG SỨC ƯỚC LƯỢNG')} →</span>{state.options.map((o,i)=><button key={o.id} className={'lens-point '+(state.chosen===o.id?'selected':'')} style={{left:`${({low:20,medium:48,high:77,unknown:88})[o.effort]}%`,bottom:`${({low:23,medium:50,high:76,unknown:12})[o.impact]+(o.impact==='unknown'?i*8:0)}%`}} onClick={()=>{setState(s=>({...s,chosen:o.id}));setEdit(o.id);}}><i/>{c(o.title)}</button>)}</div><p className="caption">{t('Unknown estimates appear at the right/bottom edge; this is not a ranking.','Ước lượng chưa rõ nằm ở cạnh phải/dưới; đây không phải xếp hạng.')}</p><div className="table-wrap"><table><thead><tr><th>{t('Alternative','Phương án')}</th><th>{t('Impact assumption','Giả định tác động')}</th><th>{t('Effort estimate','Ước lượng công sức')}</th><th>{t('Risk','Rủi ro')}</th></tr></thead><tbody>{state.options.map(o=><tr key={o.id}><th><button className="text-link" onClick={()=>setEdit(o.id)}>{c(o.title)}</button></th><td>{translateCategory(o.impact,t)}</td><td>{translateCategory(o.effort,t)}</td><td>{c(o.risk)}</td></tr>)}</tbody></table></div></Card>}{edit&&state.options.find(o=>o.id===edit)&&<Card title={t('Edit an alternative','Sửa phương án')} className="option-editor">{(()=>{const o=state.options.find(o=>o.id===edit);return <><div className="two-col"><Input label={t('Title','Tiêu đề')} value={c(o.title)} onChange={e=>updateOption(o.id,{title:e.target.value})}/><Input label={t('Mechanism','Cơ chế')} value={c(o.mechanism)} onChange={e=>updateOption(o.id,{mechanism:e.target.value})}/><Select label={t('Impact (assumption)','Tác động (giả định)')} value={o.impact} options={['low','medium','high','unknown'].map(v=>[v,translateCategory(v,t)])} onChange={e=>updateOption(o.id,{impact:e.target.value})}/><Select label={t('Effort (estimate)','Công sức (ước lượng)')} value={o.effort} options={['low','medium','high','unknown'].map(v=>[v,translateCategory(v,t)])} onChange={e=>updateOption(o.id,{effort:e.target.value})}/><Textarea label={t('Risk / opportunity cost','Rủi ro / chi phí cơ hội')} value={c(o.risk)} onChange={e=>updateOption(o.id,{risk:e.target.value})}/><Textarea label={t('Validation plan','Kế hoạch xác minh')} value={c(o.validation)} onChange={e=>updateOption(o.id,{validation:e.target.value})}/></div><Input label={t('Confidence rationale','Lý do đánh giá độ tin cậy')} value={c(o.confidence)} onChange={e=>updateOption(o.id,{confidence:e.target.value})}/><div className="row end"><Button quiet onClick={async()=>{if(await confirm(t('Delete this alternative?','Xóa phương án này?'),t('Keep at least two alternatives to save a decision.','Giữ ít nhất hai phương án để lưu quyết định.'))){setState(s=>({...s,options:s.options.filter(x=>x.id!==o.id),chosen:s.chosen===o.id?null:s.chosen}));setEdit(null);}}}>{t('Delete','Xóa')}</Button><Button secondary onClick={()=>{const copy={...o,id:'O-'+Date.now(),title:c(o.title)+' '+t('(copy)','(bản sao)')};setState(s=>({...s,options:[...s.options,copy]}));}}>{t('Duplicate','Nhân bản')}</Button><Button onClick={()=>setEdit(null)}>{t('Done','Xong')}</Button></div></>;})()}</Card>}<Card title={t('The Decision Record','Hồ sơ quyết định')} className="record-writer"><div className="two-col"><Textarea label={t('What we believe — hypothesis','Điều ta tin — giả thuyết')} value={c(state.hypothesis)} onChange={e=>setState(s=>({...s,hypothesis:e.target.value}))}/><Textarea label={t('Why this bet — rationale & trade-offs','Vì sao chọn — lý do & đánh đổi')} value={c(state.rationale)} rows={5} onChange={e=>setState(s=>({...s,rationale:e.target.value}))}/></div><Textarea label={t('When would we revisit this decision?','Khi nào cần xem lại quyết định?')} value={c(state.revisit)} onChange={e=>setState(s=>({...s,revisit:e.target.value}))}/><div className="record-summary"><span>{t('Primary metric','Chỉ số chính')}: <strong>{EVENTS[config.primaryIndex]+' / '+EVENTS[0]}</strong></span><span>{t('Guardrail','Chỉ số giới hạn')}: {c(config.guardrail)}</span><span>{t('Rejected alternatives','Phương án không chọn')}: {state.options.filter(o=>o.id!==state.chosen).map(o=>c(o.title)).join(' · ')}</span></div>{errors.length>0&&<div className="form-errors" role="alert">{errors.map(e=><p key={e}>{e}</p>)}</div>}<div className="row end"><span className="caption">{t('Draft edits saved on this device. A decision is recorded only when you save.','Bản nháp lưu trên thiết bị. Hồ sơ quyết định chỉ tạo khi bạn bấm lưu.')}</span><Button arrow onClick={save}><Save size={16}/>{t('Save Decision & Build Experiment','Lưu quyết định & lập thử nghiệm')}</Button></div></Card><DecisionDNA/></>;
}
function defaultExperiment(decision,t){if(decision.case_id&&decision.case_id!=='orbitdesk')return caseExperiment(decision,t);return {id:'EXP-'+decision.id,decision_id:decision.id,title:decision.title,hypothesis:decision.hypothesis,population:t('New solo evaluators entering onboarding','Người dùng mới tự tìm hiểu khi onboarding'),unit:'unique_user',method:'usability',numerator:EVENTS[3],denominator:EVENTS[0],days:7,baseline:decision.baseline.counts[0]?decision.baseline.counts[3]/decision.baseline.counts[0]*100:0,target:22,alpha:.05,power:.8,control:t('Mandatory team invitation before first value.','Bắt buộc mời đội nhóm trước giá trị đầu tiên.'),treatment:decision.options.find(o=>o.id===decision.chosen)?.mechanism||'',guardrail:t('Team invitation rate among signup users; mobile errors if instrumented.','Tỷ lệ mời đội nhóm trong người đăng ký; lỗi điện thoại nếu có đo.'),rule:t('Ship only after the predeclared practical threshold is supported and invitation/error guardrails stay within agreed tolerances. Iterate if promising but usability remains weak. Stop if cost outweighs evidence. Otherwise inconclusive.','Chỉ triển khai khi có đủ bằng chứng đạt ngưỡng thực tiễn đã định và chỉ số mời/lỗi trong giới hạn. Sửa nếu có triển vọng nhưng trải nghiệm còn yếu. Dừng nếu chi phí vượt bằng chứng. Nếu chưa đủ, không kết luận.'),start:'',end:'',notes:'',status:'draft'};}
function Experiment(){const {t,c,state,setState,decision,toast,n,confirm,navigate,stepEvents:EVENTS,stepLabels:eventLabels,config,unit}=useApp();if(!decision)return <><SectionHead index={3}/><Card><Empty icon={FlaskConical} title={t('An experiment needs a saved bet.','Thử nghiệm cần quyết định đã lưu.')} body={t('Compare alternatives and save a decision first. Your draft reasoning is still in the canvas.','So sánh phương án và lưu quyết định trước. Bản nháp vẫn ở phần quyết định.')}><Button to="/lab/decide" arrow>{t('Return to Decision Canvas','Về phần ra quyết định')}</Button></Empty></Card></>;
 const exp={...(state.experiments[decision.id]||{}),...(state.experimentDrafts?.[decision.id]||state.experiments[decision.id]||defaultExperiment(decision,t))};
 const update=(key,value)=>setState(s=>({...s,experimentDrafts:{...s.experimentDrafts,[decision.id]:{...exp,[key]:value}}}));const size=sampleSize(Number(exp.baseline)/100,Number(exp.target)/100,Number(exp.alpha),Number(exp.power));
 const save=async()=>{if(!(Number(exp.days)>=1&&Number(exp.days)<=365)||!exp.hypothesis.trim()||!exp.population.trim()||!exp.rule.trim()||!(Number(exp.target)>0&&Number(exp.target)<100)||exp.numerator===exp.denominator){toast(t('Complete the hypothesis, audience, valid target, distinct metric events and decision rules.','Điền giả thuyết, đối tượng, mục tiêu hợp lệ, sự kiện chỉ số khác nhau và quy tắc quyết định.'));return;}
  const old=state.experiments[decision.id];if(old?.pre_result_snapshot&&JSON.stringify(old.pre_result_snapshot)!==JSON.stringify({...exp,pre_result_snapshot:undefined,history:undefined})){if(!await confirm(t('Change a plan after results were imported?','Sửa kế hoạch sau khi nhập kết quả?'),t('Your original pre-result snapshot will be preserved. Interpret changes as post-hoc.','Bản chụp trước kết quả được giữ. Những thay đổi này là sau khi biết kết quả.')))return;}
  const snapshot={...exp,status:'ready',pre_result_snapshot:old?.pre_result_snapshot||exp.pre_result_snapshot,saved_at:new Date().toISOString(),history:old?[...(old.history||[]),{...old,history:undefined}]:[]};setState(s=>({...s,experiments:{...s.experiments,[decision.id]:snapshot},activity:[...s.activity,{label:['Experiment plan saved','Đã lưu kế hoạch thử nghiệm'],at:new Date().toISOString()}]}));toast(t('Experiment plan saved locally.','Đã lưu kế hoạch trên thiết bị.'));navigate('/lab/deliver');};
 return <><SectionHead index={3}/><div className="context-line"><Badge type="teal">{decision.id}</Badge><span>{decision.title}</span><Badge type="amber">{t('PLAN, NOT RESULT','KẾ HOẠCH, CHƯA PHẢI KẾT QUẢ')}</Badge></div><div className="experiment-layout"><div className="stack"><Card title={t('01 / Hypothesis & audience','01 / Giả thuyết & đối tượng')}><Input label={t('Experiment title','Tên thử nghiệm')} value={exp.title} onChange={e=>update('title',e.target.value)}/><Textarea label={t('What do we believe will change, for whom and why?','Điều gì sẽ thay đổi, với ai và vì sao?')} value={exp.hypothesis} onChange={e=>update('hypothesis',e.target.value)}/><div className="two-col"><Input label={t('Population','Đối tượng')} value={exp.population} onChange={e=>update('population',e.target.value)}/><Select label={t('Assignment unit','Đơn vị phân nhóm')} value={exp.unit} options={['unique_'+config.unit]} onChange={e=>update('unit',e.target.value)}/></div></Card><Card title={t('02 / Metrics & guardrails','02 / Chỉ số & giới hạn')}><div className="two-col"><Select label={t('Numerator event','Sự kiện tử số')} value={exp.numerator} options={EVENTS.map((v,i)=>[v,`${c(eventLabels[i])} (${v})`])} onChange={e=>update('numerator',e.target.value)}/><Select label={t('Denominator event','Sự kiện mẫu số')} value={exp.denominator} options={EVENTS.map((v,i)=>[v,`${c(eventLabels[i])} (${v})`])} onChange={e=>update('denominator',e.target.value)}/><Input label={t('Observation window (days)','Cửa sổ theo dõi (ngày)')} type="number" min="1" max="365" value={exp.days} onChange={e=>update('days',Number(e.target.value))}/><Input label={t('Illustrative target (%)','Mục tiêu minh họa (%)')} type="number" min=".1" max="99.9" step=".1" value={exp.target} onChange={e=>update('target',e.target.value)}/></div><div className="metric-definition"><span className="eyebrow">{t('COUNTING UNIT: DISTINCT','ĐƠN VỊ DUY NHẤT:')+' '+unit.toUpperCase()}</span><code>{exp.numerator} / {exp.denominator}</code><p>{exp.days} {t('days from cohort entry. A target is a planning assumption, not a prediction.','ngày từ khi bắt đầu cohort. Mục tiêu là giả định kế hoạch, không phải dự báo.')}</p></div><Textarea label={t('Guardrail definitions & tolerances','Định nghĩa chỉ số giới hạn & mức cho phép')} value={exp.guardrail} onChange={e=>update('guardrail',e.target.value)}/><p className="caption">{t('Guardrails are definitions until measured data is provided.','Chỉ số giới hạn mới là định nghĩa đến khi có dữ liệu đo.')}</p></Card><Card title={t('03 / Method & experience','03 / Phương pháp & trải nghiệm')}><Select label={t('Validation method','Phương pháp xác minh')} value={exp.method} options={[['usability',t('Prototype / moderated usability','Prototype / kiểm thử có điều phối')],['unmoderated',t('Unmoderated task test','Kiểm thử nhiệm vụ tự thực hiện')],['ab_test',t('A/B experiment','Thử nghiệm A/B')],['prepost',t('Pre/post diagnostic (confounding risk)','So sánh trước/sau (nguy cơ nhiễu)')]]} onChange={e=>update('method',e.target.value)}/>{exp.method==='prepost'&&<div className="notice amber"><Info size={18}/><p>{t('Pre/post changes may reflect seasonality, cohort differences or other interventions. Do not infer causation from uplift alone.','Thay đổi trước/sau có thể do mùa vụ, cohort hoặc can thiệp khác. Không suy ra nguyên nhân từ mức tăng.')}</p></div>}<div className="two-col"><Textarea label={t('Control experience','Trải nghiệm đối chứng')} value={exp.control} onChange={e=>update('control',e.target.value)}/><Textarea label={t('Treatment experience','Trải nghiệm thử nghiệm')} value={exp.treatment} onChange={e=>update('treatment',e.target.value)}/><Input label={t('Planned start','Ngày bắt đầu dự kiến')} type="date" value={exp.start} onChange={e=>update('start',e.target.value)}/><Input label={t('Planned end','Ngày kết thúc dự kiến')} type="date" value={exp.end} onChange={e=>update('end',e.target.value)}/></div></Card><Card title={t('04 / Predeclared decision rules','04 / Quy tắc quyết định trước thử nghiệm')}><Textarea rows={5} label={t('When will we Ship, Iterate, Stop or remain Inconclusive?','Khi nào triển khai, sửa, dừng hoặc chưa kết luận?')} value={exp.rule} onChange={e=>update('rule',e.target.value)}/><Textarea label={t('Analyst notes','Ghi chú phân tích')} value={exp.notes} onChange={e=>update('notes',e.target.value)}/>{exp.pre_result_snapshot&&<Badge type="amber">{t('Original pre-result rules preserved','Đã giữ quy tắc trước kết quả')}</Badge>}</Card><div className="row end"><Button secondary onClick={()=>download('betterbet-experiment-'+decision.id+'.json',JSON.stringify(exp,null,2),'application/json')}><Download size={16}/>{t('Export Plan','Xuất kế hoạch')}</Button><Button onClick={save} arrow>{t('Save Plan & Create Brief','Lưu kế hoạch & tạo bản triển khai')}</Button></div></div><aside className="experiment-rail"><Card title={t('Planning snapshot','Tóm tắt kế hoạch')}><Badge type="amber">{t('ILLUSTRATIVE ASSUMPTIONS','GIẢ ĐỊNH MINH HỌA')}</Badge><div className="planning-summary"><span>{t('Editable planning baseline','Tỷ lệ nền để lập kế hoạch')}</span><strong><CountUp value={Number(exp.baseline)} kind="decimal" language={state.language}/><small>%</small></strong><ArrowRight size={22}/><span>{t('Proposed goal','Mục tiêu dự kiến')}</span><strong><CountUp value={Number(exp.target)} kind="decimal" language={state.language}/><small>%</small></strong><p>{(Number(exp.target)-Number(exp.baseline)).toFixed(2)} {t('percentage points · assumed','điểm phần trăm · giả định')}</p></div><p>{t('The decision baseline is a saved data snapshot. These planning inputs do not rewrite it.','Hiện trạng của quyết định là bản chụp đã lưu. Đầu vào lập kế hoạch không sửa bản chụp đó.')}</p></Card><Card title={t('Approximate A/B sample','Ước lượng mẫu A/B')}><Input label={t('Baseline conversion (%)','Tỷ lệ nền (%)')} type="number" min=".1" max="99.9" step=".1" value={exp.baseline} onChange={e=>update('baseline',e.target.value)}/><div className="two-col"><Select label="Alpha" value={exp.alpha} options={[[.05,'0.05'],[.1,'0.10'],[.01,'0.01']]} onChange={e=>update('alpha',Number(e.target.value))}/><Select label={t('Power','Power (lực kiểm định)')} value={exp.power} options={[[.8,'80%'],[.9,'90%'],[.95,'95%']]} onChange={e=>update('power',Number(e.target.value))}/></div><div className="sample-size"><strong><CountUp value={size} language={state.language}/></strong><span>{unit+' '+t('per arm · equal split','mỗi nhóm · chia đều')}</span></div><details><summary>{t('Method & limitations','Phương pháp & giới hạn')}</summary><p>{t('Two-sided independent two-proportion normal approximation. No sequential monitoring, clustering, interference, multiple comparisons or implementation losses. Planning only.','Xấp xỉ chuẩn hai tỷ lệ độc lập, kiểm định hai phía. Không gồm theo dõi tuần tự, cụm, tương tác, nhiều so sánh hoặc hao hụt triển khai. Chỉ để lập kế hoạch.')}</p></details></Card><Card title={t('Start small','Bắt đầu nhỏ')}><p>{t('For uncertain mechanisms, a prototype study often earns the next experiment. This product does not run tests or assign live users.','Với cơ chế chưa rõ, nghiên cứu prototype giúp quyết định thử nghiệm tiếp theo. Sản phẩm chưa tự chạy test hay phân nhóm người dùng trực tiếp.')}</p></Card></aside></div></>;
}
function generateBrief(decision,exp,t){if(decision.case_id&&decision.case_id!=='orbitdesk')return caseBrief(decision,exp,t);return `# ${exp.title}\n\n${t('Status: Draft — pending validation','Trạng thái: Bản nháp — chờ xác minh')}\n${t('Decision','Quyết định')}: ${decision.id}\n${t('Dataset provenance','Nguồn dữ liệu')}: ${decision.provenance}\n${t('Source IDs','ID nguồn')}: ${decision.evidence.map(e=>e.id).join(', ')}\n\n## 1. ${t('Problem & observation','Vấn đề & quan sát')}\n${decision.observation}\n\n## 2. ${t('Hypothesis & rationale','Giả thuyết & lý do')}\n${decision.hypothesis}\n${decision.rationale}\n\n## 3. ${t('User need / JTBD','Nhu cầu người dùng / JTBD')}\n${t('As a new evaluator, I want to experience meaningful value before committing my team, so I can assess whether the product fits our needs.','Là người dùng mới, tôi muốn trải nghiệm giá trị trước khi mời đội nhóm để đánh giá sản phẩm có phù hợp không.')}\n\n## 4. ${t('Chosen scope','Phạm vi đã chọn')}\n${decision.options.find(o=>o.id===decision.chosen)?.mechanism}\n${t('Validate this scope before committing to a broad rollout. Preserve the invitation path and label preview content clearly.','Xác minh phạm vi trước khi triển khai rộng. Giữ đường dẫn mời đội nhóm và ghi rõ nội dung xem thử.')}\n\n## 5. ${t('Out of scope & trade-offs','Ngoài phạm vi & sự đánh đổi')}\n${t('Full onboarding rebuild, enterprise permissions and pricing changes are out of scope.','Ngoài phạm vi: làm lại toàn bộ onboarding, phân quyền doanh nghiệp và thay đổi giá.')}\n${decision.options.filter(o=>o.id!==decision.chosen).map(o=>'- '+o.title).join('\n')}\n\n## 6. ${t('User stories & acceptance criteria','User story & tiêu chí nghiệm thu')}\n${t('Given a user has created a workspace, when they reach the next onboarding step, then the selected treatment is clearly presented and existing invitation behavior remains available.\nGiven sample preview content is shown, when the user opens it, then it is clearly labeled as sample content.\nGiven an invitation fails, when an error is shown, then the user can retry without duplicate submissions.\nGiven a session is interrupted, when the user returns, then progress is restored without double-counting identities or events.','Khi người dùng đã tạo workspace và đến bước tiếp theo, phương án thử nghiệm phải được trình bày rõ; chức năng mời hiện tại vẫn sử dụng được.\nKhi người dùng mở nội dung xem thử, phải ghi rõ đó là nội dung mẫu.\nKhi lời mời thất bại và hiện lỗi, người dùng có thể thử lại mà không gửi trùng.\nKhi phiên bị gián đoạn và người dùng quay lại, tiến độ được khôi phục, không đếm trùng người dùng hay sự kiện.')}\n\n## 7. ${t('Business rules','Quy tắc nghiệp vụ')}\n${t('Never send an invitation without explicit user action. Keep assignment stable per user if an A/B test is implemented. The revised flow must be reversible.','Không gửi lời mời khi chưa có hành động rõ của người dùng. Giữ nhóm thử nghiệm ổn định cho mỗi người nếu chạy A/B. Luồng thay đổi phải có thể hoàn nguyên.')}\n\n## 8. ${t('Edge cases','Tình huống biên')}\n${t('No teammates; email service failure; slow connection; invited user joining an existing team; repeated value events; device changes; keyboard-only navigation.','Không có đồng đội; lỗi dịch vụ email; mạng chậm; người được mời vào nhóm hiện tại; sự kiện giá trị lặp lại; đổi thiết bị; chỉ dùng bàn phím.')}\n\n## 9. ${t('Non-functional requirements','Yêu cầu phi chức năng')}\n${t('Readable responsive UI, visible keyboard focus, accessible controls, safe errors, anonymized analytics identities and graceful reduced-motion behavior.','Giao diện dễ đọc và responsive, focus bàn phím rõ, điều khiển tiếp cận được, lỗi an toàn, ẩn danh ID phân tích và giảm chuyển động phù hợp.')}\n\n## 10. ${t('Event tracking plan','Kế hoạch ghi sự kiện')}\n| Event | ${t('Trigger','Thời điểm')} | Properties |\n|---|---|---|\n| preview_option_seen | ${t('Option becomes visible','Lựa chọn hiện ra')} | user_id, timestamp, experiment_variant, onboarding_step |\n| preview_entered | ${t('User opens preview','Người dùng mở xem thử')} | user_id, timestamp, session_id, experiment_variant |\n| ${exp.numerator} | ${t('Defined milestone completed','Hoàn thành mốc đã định')} | user_id, timestamp, entry_path, experiment_variant |\n| teammate_invited | ${t('Invitation submitted successfully','Gửi lời mời thành công')} | user_id, timestamp, invitation_count, experiment_variant |\n| onboarding_error | ${t('Blocking error shown','Hiện lỗi chặn')} | user_id, timestamp, error_code, device |\n\n## 11. ${t('Dependencies & release plan','Phụ thuộc & kế hoạch phát hành')}\n${t('Prototype validation → design review → event instrumentation → mobile QA → analytics verification → limited release with rollback.','Xác minh prototype → duyệt thiết kế → ghi sự kiện → QA điện thoại → xác minh phân tích → phát hành giới hạn có hoàn nguyên.')}\n\n## 12. ${t('Measurement & decision rules','Đo lường & quy tắc quyết định')}\n${exp.numerator} / ${exp.denominator}; ${exp.days} ${t('days, distinct users','ngày, người dùng duy nhất')}.\n${t('Method','Phương pháp')}: ${exp.method}\n${t('Guardrail','Chỉ số giới hạn')}: ${exp.guardrail}\n${exp.rule}\n\n---\n${t('Editable rules-assisted draft. No research or outcome is claimed.','Bản nháp theo quy tắc, có thể chỉnh sửa. Chưa khẳng định nghiên cứu hay kết quả.')}\nDesign and Develop by Vinh Nguyen\nhttps://vinh-nguyen-portfolio-three.vercel.app/\n`;}
function Deliver(){const {t,state,setState,decision,toast,confirm,navigate,stepEvents:EVENTS,stepLabels:eventLabels,config,unit}=useApp();const exp=decision&&state.experiments[decision.id];if(!decision||!exp)return <><SectionHead index={4}/><Card><Empty icon={Code2} title={t('Give the brief a connected plan.','Gắn kế hoạch trước khi tạo bản triển khai.')} body={t('Save a decision and an experiment plan to create an editable draft from the actual record.','Lưu quyết định và kế hoạch thử nghiệm để tạo bản nháp từ hồ sơ thực tế.')}><Button to={decision?'/lab/experiment':'/lab/decide'} arrow>{t('Build the linked plan','Xây kế hoạch liên kết')}</Button></Empty></Card></>;
 const brief=state.briefs[decision.id];const generate=async()=>{if(brief&&!await confirm(t('Replace your current brief?','Thay bản triển khai hiện tại?'),t('Export first if you want to keep your edits. The new draft uses the saved decision and experiment.','Xuất trước nếu muốn giữ chỉnh sửa. Bản mới dùng quyết định và thử nghiệm đã lưu.')))return;setState(s=>({...s,briefs:{...s.briefs,[decision.id]:{id:'BRIEF-'+decision.id,decision_id:decision.id,experiment_id:exp.id,title:exp.title,content:generateBrief(decision,exp,t),updated_at:new Date().toISOString()}},activity:[...s.activity,{label:['Delivery brief drafted','Đã tạo bản triển khai'],at:new Date().toISOString()}]}));toast(t('Editable draft created from linked records.','Đã tạo bản nháp từ hồ sơ liên kết.'));};
 return <><SectionHead index={4}/><div className="context-line"><Badge type="teal">{decision.id}</Badge><span>{exp.title}</span><Badge type="amber">{t('DRAFT — PENDING VALIDATION','BẢN NHÁP — CHỜ XÁC MINH')}</Badge></div>{brief?<div className="delivery-layout"><Card className="brief-outline" title={t('Brief outline','Cấu trúc bản triển khai')}>{[t('Problem & observation','Vấn đề & quan sát'),t('Hypothesis & rationale','Giả thuyết & lý do'),t('User need / JTBD','Nhu cầu / JTBD'),t('Scope & alternatives','Phạm vi & phương án'),t('Acceptance criteria','Tiêu chí nghiệm thu'),t('Business rules','Quy tắc nghiệp vụ'),t('Edge cases','Tình huống biên'),t('Event tracking','Ghi sự kiện'),t('Release & measurement','Phát hành & đo lường')].map((x,i)=><div key={x}><span>{String(i+1).padStart(2,'0')}</span>{x}</div>)}<hr/><p className="caption">{t('A rules-assisted template, edited by you.','Bản mẫu theo quy tắc, do bạn chỉnh sửa.')}</p></Card><Card className="brief-editor"><div className="row between"><h2>{t('The working draft','Bản nháp triển khai')}</h2><Badge>{t('MARKDOWN','MARKDOWN')}</Badge></div><label className="sr-only" htmlFor="brief-content">{t('Edit delivery brief','Sửa bản triển khai')}</label><textarea id="brief-content" className="markdown-editor" value={brief.content} onChange={e=>setState(s=>({...s,briefs:{...s.briefs,[decision.id]:{...brief,content:e.target.value,updated_at:new Date().toISOString()}}}))}/><div className="row between"><span className="caption">{t('Edits stored locally. Export for backup.','Sửa đổi lưu cục bộ. Xuất để sao lưu.')}</span><Button onClick={()=>{download('betterbet-brief-'+decision.id+'.md',brief.content,'text/markdown');toast(t('Markdown download started.','Đã bắt đầu tải Markdown.'));}}><Download size={16}/>{t('Export Markdown','Xuất Markdown')}</Button></div></Card><aside className="brief-references"><Card title={t('Linked sources','Nguồn liên kết')}>{decision.evidence.map(e=><Link key={e.id} to="/lab/evidence" className="brief-ref"><span>{e.id}</span><p>{e.body}</p></Link>)}<hr/><Link to="/lab/experiment" className="text-link">{t('Experiment plan','Kế hoạch thử nghiệm')}<ArrowUpRight size={16}/></Link></Card><Button quiet onClick={generate}>{t('Regenerate Draft','Tạo lại bản nháp')}</Button><Button secondary onClick={async()=>{const content=brief.content.split(/## 6\./)[1]?.split(/## 7\./)[0]||brief.content;try{await navigator.clipboard.writeText(content);toast(t('Acceptance criteria copied.','Đã sao chép tiêu chí nghiệm thu.'));}catch{toast(t('Clipboard unavailable. Export the brief instead.','Không dùng được clipboard. Hãy xuất bản triển khai.'));}}}><Copy size={16}/>{t('Copy Criteria','Sao chép tiêu chí')}</Button></aside></div>:<Card><Empty icon={FileText} title={t('Turn the bet into buildable work.','Biến quyết định thành công việc cụ thể.')} body={t('Generate an editable twelve-section brief using your saved option, evidence and experiment.','Tạo bản triển khai 12 phần từ phương án, bằng chứng và thử nghiệm đã lưu.')}><Button onClick={generate} arrow>{t('Generate Draft Brief','Tạo bản triển khai nháp')}</Button></Empty></Card>}<Next to="/lab/review" title={t('Revisit the Original Bet','Xem lại quyết định ban đầu')} body={t('Import measured outcomes or explore a clearly labeled scenario.','Nhập kết quả đo hoặc khám phá kịch bản được ghi rõ giả lập.')}/></>;
}
function Review(){const {t,n,percent,state,setState,decision,outcomes,toast,stepEvents:EVENTS,stepLabels:eventLabels,config,unit}=useApp();const [view,setView]=useState('observed');const [scenario,setScenario]=useState(()=>{const cfg=decision?.case_config||config,k=cfg.primaryIndex;const baseline=decision?.baseline.counts||cfg.counts;const rate=baseline?.[0]?baseline[k]/baseline[0]*100:0;return {control:rate,treatment:Math.min(99,rate+4),sample:2000};});const result=decision&&outcomes?.[decision.id];const exp=decision&&state.experiments[decision.id];const review=decision&&(state.reviewDrafts?.[decision.id]||state.reviews[decision.id])||{final_decision:'pending',learning:''};
 const simulation=useMemo(()=>{if(scenario.control===''||scenario.treatment===''||scenario.sample===''||!(Number(scenario.control)>=0&&Number(scenario.control)<=100&&Number(scenario.treatment)>=0&&Number(scenario.treatment)<=100&&Number(scenario.sample)>=1&&Number.isInteger(Number(scenario.sample))&&Number(scenario.sample)<=1000000))return null;const size=Number(scenario.sample),ck=Math.round(size*Math.max(0,Math.min(100,Number(scenario.control)||0))/100),tk=Math.round(size*Math.max(0,Math.min(100,Number(scenario.treatment)||0))/100);return metricsFromCounts(ck,size,tk,size);},[scenario]);
 const metrics=view==='scenario'?simulation:result?.metrics;const edit=(key,value)=>{if(!decision)return;setState(s=>({...s,reviewDrafts:{...s.reviewDrafts,[decision.id]:{...review,[key]:value,provenance:view==='scenario'?'simulation':result?.provenance||'pending'}}}));};
 return <><SectionHead index={5}/><div className="metric-tabs review-tabs"><button className={view==='observed'?'active':''} onClick={()=>setView('observed')}>{t('Measured Outcomes','Kết quả đo')}</button><button className={view==='scenario'?'active':''} onClick={()=>setView('scenario')}>{t('Scenario Sandbox','Kịch bản giả lập')}</button></div>{view==='observed'&&!result?<Card className="outcome-empty"><Empty icon={ScanLine} title={t('Awaiting measured outcomes','Đang chờ kết quả đo thực tế')} body={t("You've defined a test, but no outcome dataset has been provided. Betterbet will not invent a result.",'Bạn đã định nghĩa thử nghiệm nhưng chưa nhập dữ liệu kết quả. Betterbet chưa đưa ra kết luận.')}><div className="row center"><Button to="/lab/data?type=outcomes" arrow>{t('Import Experiment Results','Nhập kết quả thử nghiệm')}</Button><Button to="/lab/experiment" secondary>{t('Review Decision Rules','Xem quy tắc quyết định')}</Button></div></Empty></Card>:<Card title={view==='scenario'?t('Explore the trade-off','Khám phá sự đánh đổi'):t('Observed conversions','Chuyển đổi quan sát')} aside={<Badge type={view==='scenario'?'amber':'teal'}>{view==='scenario'?t('SYNTHETIC SCENARIO','KỊCH BẢN GIẢ LẬP'):result?.provenance==='synthetic_demo_import'?t('IMPORTED SYNTHETIC EXAMPLE','VÍ DỤ GIẢ LẬP ĐÃ NHẬP'):t('IMPORTED OUTCOMES','KẾT QUẢ ĐÃ NHẬP')}</Badge>}>{view==='scenario'&&<><div className="notice amber"><Info size={18}/><p>{t('Illustrative scenario, not an observed result. Controls affect this sandbox only.','Kịch bản minh họa, chưa phải kết quả đo. Điều chỉnh chỉ áp dụng sandbox.')}</p></div><div className="three-col"><Input label={t('Control conversion (%)','Tỷ lệ đối chứng (%)')} type="number" min="0" max="100" step=".1" value={scenario.control} onChange={e=>setScenario({...scenario,control:e.target.value})}/><Input label={t('Treatment conversion (%)','Tỷ lệ thử nghiệm (%)')} type="number" min="0" max="100" step=".1" value={scenario.treatment} onChange={e=>setScenario({...scenario,treatment:e.target.value})}/><Input label={t('Sample per arm','Mẫu mỗi nhóm')} type="number" min="1" max="1000000" value={scenario.sample} onChange={e=>setScenario({...scenario,sample:e.target.value})}/></div>{!simulation&&<div className="form-errors" role="alert">{t('Enter conversion rates from 0 to 100 and an integer sample from 1 to 1,000,000.','Nhập tỷ lệ từ 0 đến 100 và cỡ mẫu nguyên từ 1 đến 1.000.000.')}</div>}</>}{metrics&&<><div className="outcome-grid">{['control','treatment'].map(arm=><div className="outcome-arm" key={arm}><span className="eyebrow">{arm==='control'?t('CONTROL','ĐỐI CHỨNG'):t('TREATMENT','THỬ NGHIỆM')}</span><strong><CountUp value={metrics[arm].rate} kind="percent" language={state.language}/></strong><p>{n(metrics[arm].k)} / {n(metrics[arm].n)} {unit+' '+t('converted','chuyển đổi')}</p><div className="outcome-bar"><span style={{width:`${(metrics[arm].rate||0)*100}%`}}/></div></div>)}</div><div className="impact-values"><div><span>{t('Absolute difference','Chênh lệch tuyệt đối')}</span><strong><CountUp value={metrics.difference==null?null:metrics.difference*100} kind="decimal" language={state.language}/> {t('pp','điểm %')}</strong></div><div><span>{t('Relative uplift','Mức tăng tương đối')}</span><strong><CountUp value={metrics.relative} kind="percent" language={state.language}/></strong></div><div><span>{t('Guardrails','Chỉ số giới hạn')}</span><strong>{t('Not measured','Chưa đo')}</strong></div></div>{view==='observed'&&<details className="calculation" open><summary>{t('Uncertainty & data quality','Bất định & chất lượng dữ liệu')}</summary><p>{t('95% Newcombe–Wilson interval for the absolute difference','Khoảng Newcombe–Wilson 95% cho chênh lệch tuyệt đối')}: {metrics.interval[0]===null?'—':`${(metrics.interval[0]*100).toFixed(2)} ${t('to','đến')} ${(metrics.interval[1]*100).toFixed(2)} pp`}.</p><p>{t('Independent binary user outcomes; no sequential, multiple-comparison or clustered adjustment. An interval does not mean the hypothesis is 95% true. Guardrails were not imported.','Kết quả nhị phân độc lập theo người dùng; chưa điều chỉnh theo dõi tuần tự, nhiều so sánh hay phân cụm. Khoảng này không có nghĩa giả thuyết đúng 95%. Chưa nhập chỉ số giới hạn.')}</p><p>{t('Source file','Tệp nguồn')}: {result.filename} · {result.excluded} {t('excluded rows','dòng loại')} · {t('Observation end','Cuối quan sát')}: {result.observation_end_at}</p>{result.warnings?.includes('binary')&&<p>{t('Some converted rows omit conversion timestamps. Their within-window binary outcome is taken as supplied, not independently verified.','Một số dòng chuyển đổi thiếu thời gian chuyển đổi. Kết quả trong cửa sổ được lấy từ dữ liệu đã cung cấp, chưa xác minh độc lập.')}</p>}</details>}</>}</Card>}<div className="two-col learning-loop"><Card title={t('The original bet','Quyết định ban đầu')}>{decision?<><Badge type="teal">{decision.id}</Badge><h3>{decision.title}</h3><p>{decision.hypothesis}</p><details><summary>{t('Predeclared rules','Quy tắc trước thử nghiệm')}</summary><p>{exp?.pre_result_snapshot?.rule||exp?.rule||t('No experiment saved yet.','Chưa lưu thử nghiệm.')}</p></details></>:<p>{t('Save a decision to connect the review to its original reasoning.','Lưu quyết định để gắn đánh giá với lý do ban đầu.')}</p>}</Card><Card title={t('What did we learn?','Ta đã học được gì?')}><Select label={t('Your next decision','Quyết định tiếp theo')} disabled={!decision} value={review.final_decision} options={[['pending',t('Pending','Đang chờ')],['ship',t('Ship','Triển khai')],['iterate',t('Iterate','Điều chỉnh')],['stop',t('Stop','Dừng')],['inconclusive',t('Inconclusive','Chưa đủ kết luận')]]} onChange={e=>edit('final_decision',e.target.value)}/><Textarea label={t('Learning & future question','Bài học & câu hỏi tiếp theo')} disabled={!decision} value={review.learning} onChange={e=>edit('learning',e.target.value)}/><Button disabled={!decision} onClick={()=>{if(view==='observed'&&(!result||result.provenance==='synthetic_demo_import')&&['ship','iterate','stop'].includes(review.final_decision)){toast(t('Import outcomes before claiming an outcome-based decision. You can record pending or inconclusive learning.','Nhập kết quả trước khi quyết định dựa trên kết quả. Có thể ghi nhận đang chờ hoặc chưa kết luận.'));return;}setState(s=>({...s,reviews:{...s.reviews,[decision.id]:{...review,saved_at:new Date().toISOString(),provenance:view==='scenario'?'simulation':result?.provenance||'pending'}}}));toast(t('Review saved locally with its provenance.','Đã lưu đánh giá cùng nguồn dữ liệu.'));}}>{t('Save Learning','Lưu bài học')}</Button></Card></div><Next to="/lab/decisions" title={t('Keep the Decision Trail','Giữ dấu vết quyết định')} body={t('Reopen, compare and export the reasoning behind your bet.','Mở lại, so sánh và xuất lý do của quyết định.')}/></>;
}
function ArchivePage(){const {t,c,state,setState,toast,confirm,navigate,exportDecision,activateDecision,stepEvents:EVENTS,stepLabels:eventLabels,config,unit}=useApp();const [compare,setCompare]=useState([]);const open=async d=>{if(await activateDecision(d))navigate('/lab/decide');};
 const duplicate=d=>{const id=`BET-${String(Math.max(0,...state.decisions.map(d=>Number(d.id.replace('BET-',''))||0))+1).padStart(4,'0')}`;const at=new Date().toISOString();const copy={...d,id,title:d.title+' '+t('(copy)','(bản sao)'),created_at:at,updated_at:at,history:[],parent_id:d.id};setState(s=>({...s,decisions:[...s.decisions,copy]}));toast(t('Independent copy created.','Đã tạo bản sao riêng.'));};
 return <><PageHeader eyebrow={t('THE DECISION TRAIL','DẤU VẾT QUYẾT ĐỊNH')} title={t('Decision Archive','Kho quyết định')} subtitle={t('The bet, the alternatives and the reasoning that traveled with them.','Lựa chọn, phương án khác và lý do đi cùng.')}><Button to="/lab/diagnose" secondary onClick={()=>setState(s=>({...s,activeDecision:null,options:caseOptions(config)}))}><Plus size={16}/>{t('New Investigation','Phân tích mới')}</Button></PageHeader>{state.decisions.length?<><div className="archive-grid">{state.decisions.map(d=><Card key={d.id} className="archive-card"><div className="row between"><Badge type="teal">{d.id}</Badge><Badge type={state.reviews[d.id]?.saved_at?'amber':'neutral'}>{state.reviews[d.id]?.saved_at?t('Outcome reviewed','Đã đánh giá'):state.experiments[d.id]?t('Experiment planned','Đã lập thử nghiệm'):t('Decided','Đã quyết định')}</Badge></div><h2>{d.title}</h2><p>{d.hypothesis}</p><div className="archive-meta"><span>{d.workspace} · {d.provenance==='synthetic_demo'?t('Synthetic','Giả lập'):t('Imported','Đã nhập')}</span><span>{d.evidence.length} {t('sources','nguồn')} · {d.options.length} {t('alternatives','phương án')}</span><span>{new Date(d.created_at).toLocaleDateString(state.language==='vi'?'vi-VN':'en-GB')} · {d.history?.length||0} {t('prior revisions','bản sửa trước')}</span></div><DecisionDNA decision={d}/><div className="archive-actions"><Button onClick={()=>open(d)}>{t('Open','Mở')}</Button><Button quiet onClick={()=>exportDecision(d)}><Download size={16}/>{t('Export','Xuất')}</Button><button className="icon-btn" aria-label={t('Duplicate decision','Nhân bản quyết định')} onClick={()=>duplicate(d)}><Copy size={16}/></button><button className="icon-btn danger" aria-label={t('Delete decision','Xóa quyết định')} onClick={async()=>{if(await confirm(t('Delete '+d.id+'?','Xóa '+d.id+'?'),t('Export a backup first. This permanently removes the local record.','Hãy xuất sao lưu trước. Thao tác xóa hồ sơ cục bộ.')))setState(s=>({...s,decisions:s.decisions.filter(x=>x.id!==d.id),activeDecision:s.activeDecision===d.id?null:s.activeDecision}));}}><Trash2 size={16}/></button></div><label className="check-label"><input type="checkbox" checked={compare.includes(d.id)} onChange={e=>setCompare(e.target.checked?[...compare,d.id]:compare.filter(x=>x!==d.id))}/>{t('Compare this record','So sánh hồ sơ này')}</label></Card>)}</div>{compare.length>=2&&<Card title={t('Compare saved decisions','So sánh quyết định đã lưu')}><div className="table-wrap"><table><thead><tr><th>{t('Record','Hồ sơ')}</th><th>{t('Chosen option','Phương án chọn')}</th><th>{t('Hypothesis','Giả thuyết')}</th><th>{t('Sources','Nguồn')}</th><th>{t('Dataset','Dữ liệu')}</th></tr></thead><tbody>{state.decisions.filter(d=>compare.includes(d.id)).map(d=><tr key={d.id}><th>{d.id}</th><td>{d.title}</td><td>{d.hypothesis}</td><td>{d.evidence.map(e=>e.id).join(', ')}</td><td>{d.dataset_fingerprint}</td></tr>)}</tbody></table></div></Card>}</>:<Card><Empty icon={Archive} title={t('Every bet deserves a trail.','Mỗi quyết định cần dấu vết.')} body={t('Save your first decision after comparing alternatives and linking evidence. It will live here.','Lưu quyết định đầu tiên sau khi so sánh phương án và liên kết bằng chứng. Hồ sơ sẽ ở đây.')}><Button to="/lab/diagnose" arrow>{t('Begin an Investigation','Bắt đầu phân tích')}</Button></Empty></Card>}</>;
}
function SettingsPage(){const {t,state,setState,backup,restore,reset,stepEvents:EVENTS,stepLabels:eventLabels,config,unit}=useApp();return <><PageHeader eyebrow={t('YOUR WORKSPACE','KHÔNG GIAN CỦA BẠN')} title={t('Preferences & backups','Tùy chọn & sao lưu')} subtitle={t('Local-first by design. Keep an export for work you care about.','Lưu cục bộ theo thiết kế. Xuất công việc quan trọng để sao lưu.')}/><div className="two-col"><Card title={t('Language & guidance','Ngôn ngữ & hướng dẫn')}><Select label={t('Interface language','Ngôn ngữ giao diện')} value={state.language} options={[['en','English'],['vi','Tiếng Việt']]} onChange={e=>setState(s=>({...s,language:e.target.value}))}/><label className="check-label"><input type="checkbox" checked={state.guided} onChange={e=>setState(s=>({...s,guided:e.target.checked}))}/>{t('Show guided next steps','Hiện bước tiếp theo có hướng dẫn')}</label><p>{t('Reduced motion follows your device preference. Marketing animation is removed when this preference is enabled.','Giảm chuyển động theo cài đặt thiết bị. Hiệu ứng giới thiệu được bỏ khi bật tùy chọn này.')}</p></Card><Card title={t('Portable backup','Sao lưu di động')}><p>{t('Export records, notes, plans and imported data as a versioned JSON backup. Restore only a backup you trust.','Xuất hồ sơ, ghi chú, kế hoạch và dữ liệu nhập thành JSON có phiên bản. Chỉ khôi phục bản sao đáng tin cậy.')}</p><div className="row"><Button onClick={backup}><Download size={16}/>{t('Export Workspace','Xuất không gian')}</Button><label className="btn secondary">{t('Restore Backup','Khôi phục sao lưu')}<input type="file" accept="application/json,.json" className="sr-only" onChange={e=>{if(e.target.files[0])restore(e.target.files[0]);e.target.value='';}}/></label></div></Card><Card title={t('Data privacy','Quyền riêng tư dữ liệu')}><ShieldCheck size={26}/><p>{t('CSV processing is in this browser. Imported datasets are stored in IndexedDB; small records and preferences use localStorage. Clearing browser data removes these local records. There is no cross-device or team synchronization.','CSV được xử lý trong trình duyệt. Dữ liệu nhập lưu ở IndexedDB; hồ sơ nhỏ và tùy chọn dùng localStorage. Xóa dữ liệu trình duyệt sẽ xóa hồ sơ. Chưa có đồng bộ giữa thiết bị hay đội nhóm.')}</p><p>{t('Do not import sensitive identifiers without authority. Local storage is not an enterprise secure vault.','Không nhập định danh nhạy cảm khi chưa được phép. Bộ nhớ cục bộ không phải kho doanh nghiệp bảo mật.')}</p></Card><Card title={t('Start fresh','Bắt đầu lại')}><p>{t('Reset removes local edits, decisions and imported datasets. Export first to keep a copy.','Đặt lại sẽ xóa sửa đổi, quyết định và dữ liệu nhập. Xuất trước để giữ bản sao.')}</p><Button secondary onClick={reset}>{t('Reset Local Workspace','Đặt lại không gian cục bộ')}</Button></Card></div></>;}
export default function Lab({page}){const {t,c,state,setState,route,dataset,storageError,exportDecision,decision,stepEvents:EVENTS,stepLabels:eventLabels,config,unit}=useApp();const [open,setOpen]=useState(false);useEffect(()=>setOpen(false),[route]);const stage=stages.findIndex(s=>s[0]===page);const completed=[!!state.investigation,state.evidence.some(e=>e.linked),!!decision,!!(decision&&state.experiments[decision.id]),!!(decision&&state.briefs[decision.id]),!!(decision&&state.reviews[decision.id]?.saved_at)];return <div className="lab-shell"><aside className={'sidebar '+(open?'open':'')}><div className="sidebar-brand"><Logo small/><button className="icon-btn mobile-only" onClick={()=>setOpen(false)} aria-label={t('Close navigation','Đóng điều hướng')}><X size={20}/></button></div><Link to="/lab" className="workspace-select"><span className="workspace-avatar">{dataset.provenance==='synthetic_demo'?dataset.name[0]:'D'}</span><div><strong>{dataset.name}</strong><span>{dataset.provenance==='synthetic_demo'?t('Demo workspace','Không gian demo'):t('Imported workspace','Không gian dữ liệu nhập')}</span></div><ChevronRight size={15}/></Link><nav aria-label={t('Workspace navigation','Điều hướng không gian')}><Link to="/lab/overview" className={page==='overview'?'active':''}><LayoutDashboard size={18}/>{t('Overview','Tổng quan')}</Link><span className="nav-group">{t('THE DECISION LOOP','VÒNG LẶP QUYẾT ĐỊNH')}</span>{stages.map((s,i)=>{const Icon=icons[i];return <Link key={s[0]} to={'/lab/'+s[0]} className={page===s[0]?'active':''} aria-current={page===s[0]?'page':undefined}><Icon size={18}/><span>{c([s[1],s[2]])}</span><small>{completed[i]?<Check size={13}/>:String(i+1).padStart(2,'0')}</small></Link>;})}<hr/><Link to="/lab/decisions" className={page==='decisions'?'active':''}><Archive size={18}/>{t('Decision Archive','Kho quyết định')}<small>{state.decisions.length||''}</small></Link><Link to="/lab/data" className={page==='data'?'active':''}><Database size={18}/>{t('Data Manager','Quản lý dữ liệu')}</Link><Link to="/lab/settings" className={page==='settings'?'active':''}><Settings size={18}/>{t('Settings','Cài đặt')}</Link></nav><div className="sidebar-bottom"><div className="local-status"><span className="status-dot"/>{t('Local-first workspace','Không gian lưu cục bộ')}</div><Link to="/case-study">{t('Behind the Decisions','Đằng sau quyết định')}<ArrowUpRight size={14}/></Link><Credit/></div></aside>{open&&<button className="nav-overlay" aria-label={t('Close navigation','Đóng điều hướng')} onClick={()=>setOpen(false)}/>}<div className="lab-main"><header className="lab-topbar"><div className="row"><button className="icon-btn mobile-only" aria-expanded={open} aria-label={t('Open navigation','Mở điều hướng')} onClick={()=>setOpen(true)}><Menu size={22}/></button><span className="breadcrumb">{dataset.name}<ChevronRight size={14}/>{page==='entry'?t('Welcome','Chào mừng'):stage>=0?c([stages[stage][1],stages[stage][2]]):t('Workspace','Không gian')}</span><Provenance/></div><div className="row"><span className={'save-status '+(storageError?'error':'')}><span className="status-dot"/>{storageError?t('Storage unavailable','Không thể lưu'):t('Saved on device','Đã lưu trên thiết bị')}</span><CasePicker/><Lang/><button className="top-export" onClick={()=>exportDecision(decision)}><Download size={16}/>{t('Export','Xuất')}</button></div></header><main id="main" className="lab-content">{dataset.provenance==='unavailable'&&<div className="notice rose" role="alert">{t('Original imported data is unavailable. Re-import the file. No demo data has been substituted.','Thiếu dữ liệu đã nhập. Nhập lại tệp gốc. Không thay bằng dữ liệu demo.')}</div>}{page!=='entry'&&<div className="case-context"><strong>{dataset.name}</strong><span>{unit} · {config.days} {t('days','ngày')} · {c(config.method)}</span></div>}{decision&&decision.dataset_fingerprint!==dataset.fingerprint&&<div className="notice amber"><Info size={18}/><p>{t('This saved decision references another dataset snapshot. Diagnosis shows the active dataset. Re-import the original file or save a fresh investigation before editing the record.','Quyết định đã lưu dùng bản chụp dữ liệu khác. Chẩn đoán hiển thị dữ liệu đang dùng. Nhập lại tệp gốc hoặc lưu phân tích mới trước khi sửa hồ sơ.')}</p></div>}{storageError&&<div className="notice rose" role="alert">{t('Browser storage is unavailable. Changes exist in memory only; export a backup now.','Bộ nhớ trình duyệt không khả dụng. Sửa đổi chỉ nằm trong bộ nhớ tạm; hãy xuất ngay.')}</div>}{state.guided&&stage>=0&&<div className="guide-progress"><span>{t('GUIDED INVESTIGATION','PHÂN TÍCH CÓ HƯỚNG DẪN')}</span><div>{stages.map((s,i)=><Link to={'/lab/'+s[0]} key={s[0]} className={(stage===i?'current ':'')+(completed[i]?'complete':'')} aria-label={c([s[1],s[2]])}>{completed[i]?<Check size={12}/>:i+1}</Link>)}</div><button onClick={()=>setState(s=>({...s,guided:false}))}>{t('Explore freely','Tự khám phá')}<X size={13}/></button></div>}{page==='entry'?<LabEntry/>:page==='overview'?<Overview/>:page==='diagnose'?<Diagnose/>:page==='evidence'?<Evidence/>:page==='decide'?<Decide/>:page==='experiment'?<Experiment/>:page==='deliver'?<Deliver/>:page==='review'?<Review/>:page==='decisions'?<ArchivePage/>:page==='data'?<DataManager/>:<SettingsPage/>}</main><footer className="lab-footer"><span>{t('Every bet should teach you something.','Mỗi quyết định nên giúp bạn học điều gì đó.')}</span><Credit/></footer></div></div>;}
